pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address other) internal {
        vm.assume(other != address(this));
        uint256 beforeOther;
        try c.balances(other) returns (uint256 __r) { beforeOther = __r; } catch { return; }
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.balances(address(this)) == 0 && c.balances(other) == beforeOther);
    }

    function testFuzz_run(address other) public {
